#!/bin/sh
# Generated by dock-local: creates the AWS resources referenced by the project (idempotent).
# Runs inside ministack once it is ready (docker-entrypoint-initaws.d/ready.d hook).
set -eu
export MINISTACK_ENDPOINT="${MINISTACK_ENDPOINT:-http://localhost:4566}"
say() { echo "[dock] $*"; }

{{#if services.s3}}
say "S3 buckets"
{{#each resources.buckets}}
awslocal s3api head-bucket --bucket "{{this}}" 2>/dev/null || awslocal s3api create-bucket --bucket "{{this}}" >/dev/null && say "  bucket: {{this}}"
{{/each}}
{{#if resources.buckets}}{{else}}awslocal s3api head-bucket --bucket "{{project}}-bucket" 2>/dev/null || awslocal s3api create-bucket --bucket "{{project}}-bucket" >/dev/null && say "  bucket: {{project}}-bucket (default)"
{{/if}}
{{/if}}
{{#if services.sqs}}
say "SQS queues"
{{#each resources.sqs_queues}}
awslocal sqs create-queue --queue-name "{{this}}" >/dev/null && say "  queue: {{this}}"
{{/each}}
{{#if resources.sqs_queues}}{{else}}awslocal sqs create-queue --queue-name "{{project}}-queue" >/dev/null && say "  queue: {{project}}-queue (default)"
{{/if}}
{{/if}}
{{#if services.sns}}
say "SNS topics"
{{#each resources.sns_topics}}
awslocal sns create-topic --name "{{this}}" >/dev/null && say "  topic: {{this}}"
{{/each}}
{{#if resources.sns_topics}}{{else}}awslocal sns create-topic --name "{{project}}-topic" >/dev/null && say "  topic: {{project}}-topic (default)"
{{/if}}
{{/if}}
{{#if services.dynamodb}}
say "DynamoDB tables (hash key: pk)"
{{#each resources.tables}}
awslocal dynamodb describe-table --table-name "{{this}}" >/dev/null 2>&1 || awslocal dynamodb create-table --table-name "{{this}}" \
  --attribute-definitions AttributeName=pk,AttributeType=S --key-schema AttributeName=pk,KeyType=HASH \
  --billing-mode PAY_PER_REQUEST >/dev/null && say "  table: {{this}}"
{{/each}}
{{/if}}
{{#if services.secretsmanager}}
say "Secrets Manager secrets (placeholder values - edit me)"
{{#each resources.secrets}}
awslocal secretsmanager describe-secret --secret-id "{{this}}" >/dev/null 2>&1 || awslocal secretsmanager create-secret --name "{{this}}" \
  --secret-string '{"username":"app","password":"app"}' >/dev/null && say "  secret: {{this}}"
{{/each}}
{{/if}}
{{#if services.ssm}}
say "SSM parameters (placeholder values - edit me)"
{{#each resources.parameters}}
awslocal ssm put-parameter --name "{{this}}" --type String --value "dock" --overwrite >/dev/null && say "  parameter: {{this}}"
{{/each}}
{{/if}}
{{#if services.kinesis}}
say "Kinesis streams"
{{#each resources.streams}}
awslocal kinesis describe-stream-summary --stream-name "{{this}}" >/dev/null 2>&1 || awslocal kinesis create-stream --stream-name "{{this}}" --shard-count 1 && say "  stream: {{this}}"
{{/each}}
{{/if}}
say "done"
